import { createClient } from '@supabase/supabase-js';
import { money, dollarsToCents, previewCloseout, balance, payerBalance, enrollment, sessionDisposition, localDate, localToInstant } from '../supabase/functions/_shared/ledger.mjs';

const $ = selector => document.querySelector(selector);
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const simulated = import.meta.env.DEV && location.port === '5179' && ['127.0.0.1', 'localhost'].includes(location.hostname);
const url = import.meta.env.VITE_SUPABASE_URL, publicKey = import.meta.env.VITE_SUPABASE_ANON_KEY;
const configured = url && /^https:\/\/[a-z0-9]+\.supabase\.co$/.test(url) && publicKey && !publicKey.startsWith('sb_secret_');
const auth = configured ? createClient(url, publicKey, { auth: { persistSession: false, autoRefreshToken: true, detectSessionInUrl: false } }) : null;
const endpoint = simulated ? '/__owner/api' : `${url}/functions/v1/owner-api`;
let state, tab = 'overview', selectedSession, selectedPayer, selectedPlayer, selectedTable, review, statementReview, planPeriodReview, selectedRosterDraft, setupLink, busy = false, poll, authFactor, draftTimer, draftSave = Promise.resolve();
const options = (items, selected) => items.map(([id, label]) => `<option value="${escape(id)}" ${id === selected ? 'selected' : ''}>${escape(label)}</option>`).join('');
const button = (label, action, id = '', css = '') => `<button type="button" class="${css}" data-action="${action}" data-id="${escape(id)}">${escape(label)}</button>`;
const tag = (label, tone = '') => `<span class="tag ${tone}">${escape(label.replaceAll('_', ' '))}</span>`;
const tracking = () => state?.trackingOnly !== false;
const providerName = id => ({ unknown: 'Arrangement not recorded', cashapp: 'Cash App', venmo: 'Venmo', stripe: 'Stripe', other: 'Other arrangement' }[id] || 'Arrangement not recorded');
const empty = label => `<p class="empty">${escape(label)}</p>`;
const name = (list, id) => state.ledger[list].find(x => x.id === id)?.name || 'Unidentified';
const obligationLabel = o => o.payerPlanId ? `Payer-level plan - ${o.periodStart} through ${o.periodEnd}` : `${name('players', o.playerId)} - ${name('tables', o.tableId)} - ${o.sessionDate}`;
const when = (value, timezone = 'America/Chicago') => new Intl.DateTimeFormat('en-US', { timeZone: timezone, weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(value));
const input = (label, field, value = '', type = 'text', extra = '') => `<label>${escape(label)}<input name="${escape(field)}" type="${type}" value="${escape(value)}" ${extra}></label>`;
const select = (label, field, choices, selected) => `<label>${escape(label)}<select name="${escape(field)}">${options(choices, selected)}</select></label>`;
const note = (label, field, value = '') => `<label>${escape(label)}<textarea name="${escape(field)}" maxlength="500">${escape(value)}</textarea></label>`;
const lines = (label, field, value = '') => `<label>${escape(label)}<textarea name="${escape(field)}" maxlength="4000">${escape(value)}</textarea></label>`;
function announce(message, error = false) { $('#message').textContent = message; $('#message').dataset.error = String(error); }
async function api(body) {
  const token = simulated ? 'local-proof-owner' : (await auth.auth.getSession()).data.session?.access_token;
  const r = await fetch(endpoint, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token || ''}` }, body: JSON.stringify(body), cache: 'no-store', credentials: 'omit' });
  const data = await r.json(); if (!r.ok) throw new Error(data.error || 'The private server is unavailable'); return data;
}
async function load(action = 'view') { state = await api({ action, month: $('#month')?.value || state?.overview.month }); render(); armPoll(); }
async function command(data) { state = await api({ action: 'command', command: data }); render(); armPoll(); }
function armPoll() { clearTimeout(poll); if (state.ledger.operations.some(o => ['queued', 'processing'].includes(o.status))) poll = setTimeout(() => load().catch(e => announce(e.message, true)), 2000); }
function render() {
  const nav = [['overview', 'Today'], ['sessions', 'Sessions'], ['people', 'Players & payers'], ['tables', 'Tables'], ['payments', 'Payments'], ['recovery', 'Recovery']];
  const panels = { overview, sessions, people, tables, payments, recovery };
  $('#app').innerHTML = `${simulated ? '<div class="banner">Local rehearsal · Every person, payment and feed below is fictional. No external payment can occur.</div>' : ''}<div class="shell"><aside class="sidebar"><div class="brand">20Fates <small>OWNER’S TABLE</small></div><nav class="nav" aria-label="Owner panel">${nav.map(([id, label]) => `<button type="button" data-action="nav" data-id="${id}" ${tab === id ? 'aria-current="page"' : ''}>${label}</button>`).join('')}</nav><div class="sidebar-bottom">A place for the business<br>behind the table.<br><br>${button('Sign out', 'signout', '', 'quiet')}</div></aside><main id="main" tabindex="-1"><div class="topline"><div><p class="eyebrow">Private · ${escape(simulated ? 'Local rehearsal' : 'Ben’s owner panel')}</p><h1>${escape(nav.find(n => n[0] === tab)[1])}</h1></div><div class="actions">${tag(tracking() ? 'Tracking only · no collection' : state.overview.collectionEnabled ? 'Collection enabled' : 'Collection off', tracking() ? 'good' : state.overview.collectionEnabled ? 'good' : 'warn')}${button('Sync feeds', 'refresh')}${!simulated ? button('Sign out', 'signout', '', 'quiet') : ''}</div></div>${coverageNotice()}${panels[tab]()}</main></div>`;
}
function coverageNotice() {
  const c = state.overview.coverage;
  return '<section class="notice section" aria-label="Receipt coverage"><strong>' + (c.complete ? 'Connected receipt intervals are current.' : 'Incomplete payment evidence · ' + c.gaps.length + ' gaps') + '</strong><p>Unmatched fees are recorded fees minus allocated receipts—not proof that someone has not paid. ' + (tracking() ? 'Recording a session never queues a payment.' : '') + '</p>' + (c.gaps.length ? '<details><summary>See missing evidence</summary><ul>' + c.gaps.map(g => '<li>' + escape(g) + '</li>').join('') + '</ul></details>' : '<p>Counts describe connected records and the reviewed opening period, not an independent provider balance guarantee.</p>') + '</section>';
}
function overview() {
  const d = state.overview, t = d.totals, attention = [];
  for (const s of d.needsCloseout) attention.push(`<div class="attention-item"><div><h3>${escape(name('tables', s.tableId))}</h3><p class="muted">${escape(when(s.startsAt, s.timezone))} · Needs closeout</p></div>${button('Close session', 'open-session', s.id, 'primary')}</div>`);
  if (d.attention.length) attention.push(`<div class="attention-item"><div><h3>${d.attention.length} collection ${d.attention.length === 1 ? 'record needs' : 'records need'} attention</h3><p class="muted">Review held, failed or uncertain outcomes.</p></div>${button('Review', 'nav', 'payments')}</div>`);
  if (d.unmatched.length) attention.push(`<div class="attention-item"><div><h3>${d.unmatched.length} receipt ${d.unmatched.length === 1 ? 'needs' : 'need'} a match</h3><p class="muted">Received money remains separate from unmatched recorded fees.</p></div>${button('Match payments', 'nav', 'payments')}</div>`);
  for (const [id, feed] of Object.entries(d.feeds)) if (d.coverage.providers[id].problem) attention.push(`<div class="attention-item"><div><h3>${escape(id === 'cashapp' ? 'Cash App' : id)} feed needs attention</h3><p class="muted">${escape(d.coverage.providers[id].problem)}</p></div></div>`);
  return `<section class="card attention" aria-label="Needs attention"><p class="eyebrow">First things first</p><h2>${attention.length ? 'A few things need your hand.' : 'The table is in order.'}</h2>${attention.join('') || '<p class="muted">No unclosed past sessions or unresolved payments in these records.</p>'}</section><section class="section"><div class="section-head"><h2>Money, clearly separated</h2><label class="sr-only" for="month">Selected month</label><input type="month" id="month" value="${d.month}" aria-label="Selected month"></div><div class="metrics"><article class="metric"><span>Received payments</span><strong>${money(t.received)}</strong><span class="muted">${money(t.unallocated)} still unallocated</span></article><article class="metric"><span>Recorded session and plan fees</span><strong>${money(t.expected)}</strong><span class="muted">${money(t.outstanding)} fees not matched</span></article><article class="metric"><span>Pending or unresolved</span><strong>${money(t.pending)}</strong><span class="muted">Not received money</span></article><article class="metric"><span>Refunds</span><strong>${money(t.refunds)}</strong><span class="muted">Provider fees ${money(t.providerFees)}${t.feesIncomplete ? ' · incomplete' : ''}</span></article></div><p class="muted section">Figures relate to ${d.month}. Received includes unallocated receipts, not verified profit. Refunds are cumulative refunds of these receipts, not a refund-date cash-flow total; refunded or disputed allocations need owner review.</p></section><section class="section"><div class="section-head"><h2>Your tables</h2>${button('Manage tables', 'nav', 'tables')}</div><div class="grid">${d.tables.map(tableCard).join('') || empty('Add the confirmed private roster and tables to begin.')}</div></section><section class="section two-col"><div><div class="section-head"><h2>Coming up</h2></div><div class="card">${d.upcoming.slice(0, 4).map(s => `<div class="list-item"><h3>${escape(name('tables', s.tableId))}</h3><p class="muted">${escape(when(s.startsAt, s.timezone))}</p></div>`).join('') || '<p class="muted">No future sessions recorded.</p>'}</div></div>${tracking() ? '<div><div class="section-head"><h2>Current payment arrangements</h2></div><div class="card"><p>Keep paying through the existing Cash App, Venmo or Stripe arrangement. This panel records evidence; it cannot request money or enroll anyone.</p><p class="muted section">A later Stripe transition is a separate owner decision.</p></div></div>' : `<div><div class="section-head"><h2>Moving to Stripe</h2>${button('Open payers', 'nav', 'people')}</div><div class="card">${Object.entries(d.enrollment).map(([label, count]) => `<div class="summary-line"><span>${label}</span><strong>${count}</strong></div>`).join('')}</div></div>`}</section><section class="section"><h2>Receipt connections</h2><div class="grid section">${Object.entries(d.feeds).map(([id, f]) => `<article class="card feed"><div><h3>${escape(id === 'cashapp' ? 'Cash App' : id === 'venmo' ? 'Venmo' : 'Stripe')}</h3><p>${escape(f.reason || (simulated ? 'Fictional local connection' : 'Receipt sync completed'))}</p><small>Last success: ${f.lastSuccess ? escape(when(f.lastSuccess)) : 'Never verified'}</small><small>Scanned interval: ${f.coveredFrom ? escape(when(f.coveredFrom)) : 'Unconfirmed'} through ${f.coveredThrough ? escape(when(f.coveredThrough)) : 'Unconfirmed'}</small><p>${escape(d.coverage.providers[id].problem || 'Selected interval current')}</p></div>${tag(d.coverage.providers[id].status, d.coverage.providers[id].problem ? 'warn' : 'good')}</article>`).join('')}</div></section>`;
}
function tableCard(t) { return `<article class="card table-card"><h3>${escape(t.name)}</h3><p class="muted">${t.occupiedSeats} reserved / ${t.capacity} seats · ${t.openSeats} open</p><div class="row"><span class="amount">${money(t.estimatedSessionCents)}</span><small>estimated normal session</small></div><div class="summary-line"><span>Collected for this month’s sessions</span><strong>${money(t.collectedCents)}</strong></div><div class="row"><span class="muted">Fees not matched</span><span>${money(t.outstandingCents)}</span></div></article>`; }
function sessions() {
  const s = state.ledger.sessions.find(s => s.id === selectedSession);
  if (!s) return `<div class="section-head"><p class="muted">Past sessions stay here until closed or canceled.</p>${button('Schedule the next month', 'schedule')}</div><div class="stack">${[...state.ledger.sessions].sort((a, b) => b.startsAt.localeCompare(a.startsAt)).map(s => `<article class="card"><div class="row"><div><h3>${escape(name('tables', s.tableId))}</h3><p class="muted">${escape(when(s.startsAt, s.timezone))} · ${escape(s.timezone)}</p></div><div class="actions">${tag(sessionDisposition(state.ledger, s), s.endsAt <= state.overview.now && !s.approvedAt && s.status !== 'canceled' ? 'warn' : '')}${button(s.approvedAt ? 'View closeout' : 'Open session', 'open-session', s.id)}</div></div></article>`).join('') || empty('Create a table, then generate its scheduled sessions.')}</div>`;
  const heading = `<div class="section-head"><div><h2>${escape(name('tables', s.tableId))}</h2><p class="muted">${escape(when(s.startsAt, s.timezone))} · ${escape(s.timezone)}</p></div>${button('All sessions', 'all-sessions')}</div>`;
  if (s.status === 'canceled') return heading + `<div class="card"><h3>Canceled · no charge</h3><p>${escape(s.canceledReason)}</p></div>`;
  if (s.approvedAt) return heading + `<section class="card"><div class="row"><h2>${s.review.rows.every(r => r.payerPlanId) ? 'Covered session recorded' : s.review.rows.every(r => r.collectionEligible === false) ? 'Session fees recorded' : 'Approved closeout'}</h2>${tag(sessionDisposition(state.ledger, s))}</div><p class="muted">${s.minutes} minutes · approved ${escape(when(s.approvedAt))}</p>${s.review.rows.map(r => `<div class="summary-line"><div><h3>${escape(r.playerName)}</h3><small>${escape(r.disposition)} · ${escape(r.attendance)} · ${r.fixedCents === null ? money(r.rateCents) + '/hour' : 'fixed fee'} · ${money(r.capCents)} cap</small></div><strong>${money(r.amountCents)}</strong></div>`).join('')}<p class="notice">${s.review.rows.every(r => r.payerPlanId) ? 'Covered by the payer-level plan. No session fee, invoice, charge, collection backlog, or table income was created.' : s.review.rows.every(r => r.collectionEligible === false) ? 'Record only. No invoice, charge or collection backlog was created. Match incoming receipts in Payments; recording is not proof of payment.' : sessionDisposition(state.ledger, s) === 'complete' ? 'This closeout is recorded. Payment results and deferred balances are preserved below.' : 'This closeout has unresolved rows. It is not marked complete.'}</p>${operationCards(state.ledger.operations.filter(o => o.items.some(i => state.ledger.obligations.find(x => x.id === i.obligationId)?.sessionId === s.id)))}</section>`;
  if (review) return heading + `<section class="card"><p class="eyebrow">One final review</p><h2>${review.reviewed.minutes} minutes of play</h2><p class="muted">Every active reserved seat is included, whether present or absent.</p>${review.reviewed.rows.map(r => `<div class="summary-line"><div><h3>${escape(r.playerName)} <small>· payer ${escape(r.payerName)}</small></h3><p class="muted">${escape(r.attendance)} · ${r.fixedCents === null ? money(r.rateCents) + '/hour' : 'fixed fee'} · ${money(r.capCents)} cap</p><p class="${r.hold ? 'error' : 'muted'}">${escape(r.hold || r.destination)} · ${escape(r.disposition)}</p>${tracking() ? '<p>No payment will be requested.</p>' : `<p>Collect now: <strong>${money(r.hold ? 0 : r.collectCents)}</strong> · Keep open: ${money(r.amountCents - (r.hold ? 0 : r.collectCents))}</p>`}${r.adjustmentCents ? `<small>Calculated ${money(r.calculatedCents)}; approved session fee ${money(r.amountCents)}</small>` : ''}</div><div><small>Session fee</small><br><strong>${money(r.amountCents)}</strong></div></div>`).join('')}<div class="summary-total"><span>${review.reviewed.rows.every(r => r.payerPlanId) ? 'Covered session closeout' : tracking() ? 'Session fees to record' : 'Collect now through Stripe'}</span><strong>${money(tracking() ? review.reviewed.obligationTotalCents : review.reviewed.collectTotalCents)}</strong></div><p class="notice">${tracking() ? 'One confirmation saves these fees permanently as record-only. They cannot become automatic charges later. Received payments are matched separately.' : review.reviewed.rows.some(r => r.hold) ? 'Held rows remain visible as needing attention. They will not be collected automatically later.' : 'After confirmation, the private server keeps the approved work even if you close this page.'}</p><div class="actions">${button(tracking() ? `Record session fees ${money(review.reviewed.obligationTotalCents)}` : review.reviewed.collectTotalCents ? `Finish session and collect ${money(review.reviewed.collectTotalCents)}` : 'Record closeout · no collection', 'confirm-close', s.id, 'primary')}${button('Back to editing', 'edit-close')}</div></section>`;
  const draft = s.draft && tracking() ? { ...s.draft, rows: (s.draft.rows || []).map(r => ({ ...r, disposition: ['collect', 'partial'].includes(r.disposition) ? 'record' : r.disposition, collectCents: 0 })) } : s.draft;
  let initial; try { initial = previewCloseout(state.ledger, draft || { sessionId: s.id, minutes: Math.round((Date.parse(s.endsAt) - Date.parse(s.startsAt)) / 60000) }, state.overview.now, { trackingOnly: tracking() }); } catch (e) { return heading + `<p class="notice">${escape(e.message)}</p>` + sessionEdit(s); }
  return heading + `<form id="closeout" class="stack"><div class="card"><h2>How long did you play?</h2><p class="muted">Actual duration sets each individually agreed fee.</p><div class="form-grid section">${input('Actual minutes', 'minutes', initial.minutes, 'number', 'required min="1" max="1440" step="1"')}<div><p id="duration-label">${Math.floor(initial.minutes / 60)} hours ${initial.minutes % 60} minutes</p><small>Absence does not remove a reserved seat’s fee. You can waive it below.</small></div></div></div>${initial.rows.map(closeoutRow).join('')}<div class="actions"><button class="primary" type="submit">Review closeout</button>${button('Save draft', 'save-draft')}${button('Cancel this session', 'cancel-session', s.id, 'danger')}</div></form>${sessionEdit(s)}`;
}
function closeoutRow(r) {
  const covered = Boolean(r.payerPlanId);
  const arrangements = covered ? [['payer_plan', 'Covered by payer-level plan']] : tracking() ? [['record', 'Record fee only'], ['monthly', 'Monthly arrangement'], ['defer', 'Deferred arrangement'], ['waive', 'Waive']] : [['collect', 'Collect now'], ['partial', 'Partially collect'], ['monthly', 'Monthly statement'], ['defer', 'Defer'], ['waive', 'Waive']];
  return `<fieldset class="closeout-row" data-player="${escape(r.playerId)}"><legend>${escape(r.playerName)}</legend><div><h3>${escape(r.payerName)} <small>payer</small></h3><small>${r.fixedCents === null ? money(r.rateCents) + '/hour' : money(r.fixedCents) + ' fixed'} · ${money(r.capCents)} session cap</small><small>${escape(r.destination)}</small></div>${select('Attendance', `attendance:${r.playerId}`, [['unknown', 'Not recorded'], ['present', 'Present'], ['absent', 'Absent reserved seat']], r.attendance)}${select('Arrangement', `disposition:${r.playerId}`, arrangements, r.disposition)}${input('Final session fee ($)', `amount:${r.playerId}`, (r.amountCents / 100).toFixed(2), 'number', covered ? 'readonly' : 'min="0" max="100" step="0.01" required')}${covered || tracking() ? '' : input('Partial amount, if chosen ($)', `partial:${r.playerId}`, (r.collectCents / 100).toFixed(2), 'number', 'min="0" max="100" step="0.01"')}${covered ? '' : input(tracking() ? 'Deferred arrangement date (optional)' : 'Do not collect before (optional)', `notBefore:${r.playerId}`, r.notBefore || '', 'date')}${covered ? '<p class="muted">This covered seat creates no session fee, collection item, or table income.</p>' : `<div class="note">${note('Operational adjustment note (optional)', `note:${r.playerId}`, r.note)}</div>`}</fieldset>`;
}
function sessionEdit(s) { return `<details class="card section"><summary>Reschedule this occurrence</summary><form id="reschedule" class="stack">${input('New start in the table’s timezone', 'start', `${s.localDate}T14:00`, 'datetime-local', 'required')}${input('Expected duration in minutes', 'duration', Math.round((Date.parse(s.endsAt) - Date.parse(s.startsAt)) / 60000), 'number', 'required min="1" max="1440"')}<button type="submit">Save this occurrence’s new time</button></form></details>`; }
function people() {
  const s = state.ledger, payer = s.payers.find(p => p.id === selectedPayer), player = s.players.find(p => p.id === selectedPlayer);
  const listing = `<div class="section-head"><h2>Players</h2>${button('Add player', 'new-player')}</div><div class="stack">${s.players.map(p => `<article class="card"><div class="row"><div><h3>${escape(p.name)}</h3><p class="muted">Payer: ${escape(name('payers', p.payerId))} · ${escape(p.discord || 'Discord not recorded')}</p></div>${button('Profile', 'player', p.id)}</div></article>`).join('')}</div><div class="section-head section"><h2>Payers</h2>${button('Add payer', 'new-payer')}</div><div class="stack">${s.payers.map(p => `<article class="card"><div class="row"><div><h3>${escape(p.name)}</h3><p class="muted">${money(payerBalance(s, p.id))} fees not matched to receipts</p>${tag(tracking() ? providerName(p.paymentProvider) : enrollment(p, localDate(state.overview.now)))}</div>${button('Open payer', 'payer', p.id)}</div></article>`).join('')}</div>`;
  let detail = `<div class="card"><h2>A player and a payer can be different people.</h2><p class="muted">Keep the seat with the player and match receipts to whoever pays. Current payment arrangements stay unchanged.</p></div>`;
  if (selectedPlayer) { const p = player || {}; detail = `<form id="player-form" class="card stack"><h2>${player ? 'Player profile' : 'New player'}</h2>${input('Name', 'name', p.name || '', 'text', 'required maxlength="200"')}${select('Payer', 'payerId', s.payers.map(p => [p.id, p.name]), p.payerId)}${input('Contact email', 'email', p.email || '', 'email')}${input('Discord handle', 'discord', p.discord || '')}${note('Brief operational note', 'note', p.note)}<button type="submit" class="primary">Save player</button>${player ? `<h3>Reserved tables</h3>${s.memberships.filter(m => m.playerId === p.id).map(m => `<p>${escape(name('tables', m.tableId))} · ${m.fixedCents === null ? money(m.rateCents) + '/hour' : money(m.fixedCents) + ' fixed'} · ${money(m.capCents)} cap · ${escape(m.cadence)}<br><small>${m.from} through ${m.until || 'ongoing'}</small></p>`).join('') || '<p class="muted">No membership yet. Add a reserved seat in Tables.</p>'}` : ''}</form>`; }
  if (selectedPayer) { const p = payer || {}; detail = `<div class="stack"><form id="payer-form" class="card stack"><h2>${payer ? 'Payer details' : 'New payer'}</h2>${input('Name', 'name', p.name || '', 'text', 'required maxlength="200"')}${input('Email', 'email', p.email || '', 'email')}${select('Current payment arrangement (record only)', 'paymentProvider', [['unknown', 'Not confirmed'], ['cashapp', 'Cash App'], ['venmo', 'Venmo'], ['stripe', 'Stripe'], ['other', 'Other']], p.paymentProvider || 'unknown')}${input('Venmo receipt name (exact)', 'venmo', p.aliases?.find(a => a.provider === 'venmo')?.name || '')}${input('Cash App receipt name (exact)', 'cashapp', p.aliases?.find(a => a.provider === 'cashapp')?.name || '')}${input('Existing Stripe customer ID (optional)', 'stripeCustomerId', p.stripeCustomerId || '', 'text', p.setup ? 'readonly' : '')}${note('Brief operational note', 'note', p.note)}<button type="submit" class="primary">Save payer</button></form>${payer ? `${tracking() ? '' : `<section class="card"><h2>Stripe enrollment</h2><p>${tag(enrollment(p, localDate(state.overview.now)))}</p><p class="muted">${escape(p.setup?.label || 'No verified Stripe-hosted setup')}</p><div class="actions">${button('Generate hosted setup link', 'setup', p.id)}</div>${setupLink ? `<p class="notice">${simulated ? 'This fictional link cannot enroll anyone.' : 'Share this Stripe-hosted link yourself. The panel has sent no message.'}</p><label>Setup link<input class="link-input" readonly value="${escape(setupLink)}"></label>` : ''}<form id="authorization-form" class="stack section"><h3>Record the payer’s authorization</h3><p class="muted">A saved payment method is not consent. Record where their agreement is retained and when automatic collection may begin.</p>${input('Effective collection date', 'effectiveFrom', p.authorization?.effectiveFrom || localDate(state.overview.now), 'date', 'required')}${note('Consent evidence reference, not a copied private conversation', 'evidence', p.authorization?.evidence)}<button type="submit">Record authorization for current seats and caps</button></form>${p.authorization ? `<div class="section">${button('Revoke automatic collection', 'revoke', p.id, 'danger')}</div>` : ''}</section>`}${statementForm(p)}</div>` : ''}`; }
  return `<div class="two-col"><div>${listing}${rosterTools(s)}</div><div>${detail}</div></div>`;
}
function draftLines(value) { return String(value || '').split('\n').map(x => x.trim()).filter(Boolean); }
function planLabel(s, plan) { return `${name('payers', plan.payerId)} · ${money(plan.amountCents)} ${plan.cadence}`; }
function rosterTools(s) {
  const memberships = s.memberships.filter(m => !m.until), plans = s.payerPlans || [], drafts = s.rosterDrafts || [], draft = drafts.find(d => d.id === selectedRosterDraft);
  const draftForm = `<form id="roster-draft-form" class="card stack"><h2>${draft ? 'Review unresolved roster draft' : 'Incomplete roster or terms draft'}</h2><p class="muted">Keep known labels, term fragments and alias holds here until they can be confirmed. Drafts cannot create seats, fees, schedules, allocations, review certification or collection. Only unresolved drafts block the opening review.</p>${input('Draft label', 'label', draft?.label || '', 'text', 'required maxlength="200"')}${lines('Known facts, one per line', 'knownFacts', (draft?.knownFacts || []).join('\n'))}${lines('Alias holds, one per line', 'aliasHolds', (draft?.aliasHolds || []).join('\n'))}${lines('Unresolved terms, one per line', 'termHolds', (draft?.termHolds || []).join('\n'))}<button type="submit">${draft ? 'Save revised draft' : 'Save private draft'}</button>${draft ? button('Cancel edit', 'cancel-roster-draft') : ''}</form>`;
  const draftCards = drafts.map(d => `<article class="card"><div class="row"><div><h3>${escape(d.label)}</h3><p class="muted">${d.knownFacts.length} known facts · ${d.aliasHolds.length} alias holds · ${d.termHolds.length} term holds · ${d.resolvedAt ? `resolved ${escape(d.resolvedAt.slice(0, 10))}` : 'unresolved'} · no financial effect</p>${d.resolvedAt ? `<p class="muted">Resolution record: ${escape(d.resolutionNote)}</p>` : ''}</div><div class="actions">${d.resolvedAt ? '' : button('Review and edit', 'edit-roster-draft', d.id)}${d.resolvedAt ? '' : button('Resolve with confirmed record', 'resolve-roster-draft', d.id)}</div></div></article>`).join('');
  return `<section class="stack section"><form id="payer-plan-form" class="card stack"><h2>Payer-level flat arrangement</h2><p class="muted">Use only after the payer, covered seats, period anchor, amount, dates and paid-through date are confirmed. One reviewed amount is recorded per completed 14-day or monthly period; it can be matched to received payments but is never split across tables or charged automatically.</p>${select('Payer', 'payerId', s.payers.map(p => [p.id, p.name]))}<label>Confirmed covered reserved seats<select name="coveredMembershipIds" multiple required>${memberships.map(m => `<option value="${escape(m.id)}">${escape(name('players', m.playerId))} · ${escape(name('tables', m.tableId))}</option>`).join('')}</select></label>${input('Amount each period ($)', 'amount', '', 'number', 'min="0.01" max="1000" step="0.01" required')}${select('Cadence', 'cadence', [['fortnightly','Every 14 days'],['monthly','Monthly']], 'fortnightly')}${input('Confirmed period anchor', 'anchor', '', 'date', 'required')}${input('Effective from', 'from', '', 'date', 'required')}${input('Replacement end date (optional)', 'until', '', 'date')}${input('Paid through', 'paidThrough', '', 'date', 'required')}${note('Arrangement note (optional)', 'note')}<button type="submit">Save confirmed payer-level plan</button></form>${plans.map(plan => `<section class="card"><h3>${escape(planLabel(s, plan))}</h3><p class="muted">${plan.coveredMembershipIds.length} confirmed seats · anchor ${escape(plan.anchor)} · ${plan.from} through ${plan.until || 'ongoing'} · record-only</p><p>Reported paid through ${escape(plan.paidThrough)}. This date does not record a payment.</p><p><strong>${money(s.obligations.filter(o => o.payerPlanId === plan.id).reduce((n, o) => n + balance(s, o.id), 0))}</strong> plan fees not matched to receipts</p><form id="plan-period-form" class="stack"><input type="hidden" name="planId" value="${escape(plan.id)}">${input('Completed period start', 'periodStart', plan.anchor, 'date', 'required')}<button type="submit">Review one completed period</button></form></section>`).join('')}${planPeriodReview ? `<section class="card"><p class="eyebrow">One final review</p><h3>${escape(planLabel(s, s.payerPlans.find(p => p.id === planPeriodReview.planId)))}</h3><p>${escape(planPeriodReview.periodStart)} through ${escape(planPeriodReview.periodEnd)} · ${planPeriodReview.coveredMembershipIds.length} covered seats</p><p class="notice">${escape(planPeriodReview.destination)} This records exactly ${money(planPeriodReview.amountCents)} owed once. Reported paid-through dates do not create receipts or settle this amount; review and match actual payment evidence separately.</p>${button(`Record ${money(planPeriodReview.amountCents)} once`, 'confirm-plan-period', '', 'primary')}</section>` : ''}${draftForm}${draftCards}</section>`;
}
function statementForm(payer) {
  const owed = state.ledger.obligations.filter(o => o.payerId === payer.id && (tracking() || (!o.payerPlanId && o.collectionEligible !== false)) && balance(state.ledger, o.id) > 0);
  if (tracking()) return '<section class="card"><h2>Recorded fees and matches</h2><p class="muted">These are fees not yet matched to received payments, not a collection statement. Missing history can change the picture.</p>' + (owed.map(o => '<div class="summary-line"><div>' + escape(obligationLabel(o)) + '<br><small>' + (o.payerPlanId ? 'Payer-level amount; no table split' : 'Session fee') + (o.collectionEligible === false ? ' · permanently record-only' : ' · previous collection record') + '</small></div><strong>' + money(balance(state.ledger, o.id)) + '</strong></div>').join('') || '<p>No unmatched fees in the current records.</p>') + button('Review received payments', 'nav', 'payments') + '</section>';
  if (!owed.length) return '<section class="card"><h2>Outstanding balance</h2><p class="muted">No unpaid recorded obligations.</p></section>';
  if (statementReview) return `<section class="card"><h2>Review statement</h2>${statementReview.items.map(i => { const o = state.ledger.obligations.find(o => o.id === i.obligationId); return `<div class="summary-line"><span>${escape(name('tables', o.tableId))} · ${o.sessionDate}</span><strong>${money(i.amountCents)}</strong></div>`; }).join('')}<p class="notice">${escape(statementReview.hold || statementReview.destination)}</p><div class="actions">${button(`Collect statement ${money(statementReview.totalCents)}`, 'confirm-statement', payer.id, 'primary')}${button('Back to amounts', 'edit-statement')}</div></section>`;
  return `<form id="statement-form" class="card stack"><h2>Collect a monthly or held balance</h2><p class="muted">Enter only the amounts to collect now. Failed or uncertain attempts require provider reconciliation first.</p>${owed.map(o => input(`${name('tables', o.tableId)} · ${o.sessionDate} · ${money(balance(state.ledger, o.id))} outstanding`, o.id, '0.00', 'number', `min="0" max="${balance(state.ledger, o.id) / 100}" step="0.01"`)).join('')}<button type="submit">Review statement</button></form>`;
}
function tables() {
  const s = state.ledger;
  return `<div class="grid">${state.overview.tables.map(tableCard).join('')}</div><div class="two-col section">${tableEditor(s)}<div class="stack"><form id="membership-form" class="card stack"><h2>Reserve a seat or change future terms</h2>${select('Player', 'playerId', s.players.map(p => [p.id,p.name]))}${select('Table', 'tableId', s.tables.map(t => [t.id,t.name]))}${input('Terms effective from', 'from', localDate(state.overview.now), 'date', 'required')}<label class="inline-check"><input name="noFee" type="checkbox">No current fee — keep this seat occupied with a zero fee and zero ceiling</label>${input('Agreed hourly rate ($)', 'rate', '', 'number', 'min="0" step="0.01"')}${input('Per-session cap ($)', 'cap', '', 'number', 'min="0" max="100" step="0.01"')}${input('Fixed session fee, if agreed ($)', 'fixed', '', 'number', 'min="0" max="100" step="0.01"')}${select('Billing arrangement', 'cadence', [['weekly','After each session'],['monthly','Monthly statement'],['manual','Manual / held']], 'weekly')}<button type="submit">Save prospective terms</button></form><section class="card"><h2>End a reserved membership</h2><form id="end-membership" class="stack section">${select('Membership', 'id', s.memberships.filter(m => !m.until).map(m => [m.id,`${name('players',m.playerId)} · ${name('tables',m.tableId)}`]))}${input('First date without this reserved seat', 'until', localDate(state.overview.now), 'date', 'required')}<button type="submit">End this membership</button></form></section></div></div><p class="notice">These are private billing tables. Public campaign pages, prices and advertised openings are unchanged.</p>`;
}
function tableEditor(s) {
  const t=s.tables.find(t=>t.id===selectedTable)||{};
  return `<form id="table-form" class="card stack"><h2>Manage a private table</h2>
    ${select('Table to edit','tableEdit',[['','Add a new table'],...s.tables.map(t=>[t.id,t.name])],selectedTable||'')}
    ${input('Table name','name',t.name||'','text','required')}
    ${input('Seat capacity','capacity',t.capacity??6,'number','required min="1" max="30"')}
    ${select('Day','weekday',['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((x,i)=>[String(i),x]),String(t.weekday??5))}
    ${input('Start time','startTime',t.startTime||'18:00','time','required')}
    ${input('Timezone','timezone',t.timezone||'America/Chicago','text','required')}
    ${input('Expected minutes','normalMinutes',t.normalMinutes??240,'number','min="1" max="1440" required')}
    ${select('Future scheduling','active',[['true','Schedule future sessions'],['false','Pause future scheduling']],String(t.active!==false))}
    <p class="muted">Existing occurrences keep their dates. Reschedule or cancel them individually; approved closeouts never change.</p>
    <button class="primary" type="submit">Save table</button></form>`;
}
function operationCards(ops) { return ops.map(o => `<div class="list-item"><div class="row"><div><h3>${escape(name('payers', o.payerId))} · ${money(o.amountCents)}</h3><p class="muted">${escape(o.reason || 'Approved payment record')}</p>${o.invoiceId ? `<a rel="noreferrer" target="_blank" href="https://dashboard.stripe.com/${state.environment === 'live' ? '' : 'test/'}invoices/${encodeURIComponent(o.invoiceId)}">Inspect the existing Stripe invoice</a>` : ''}</div>${tag(o.status, o.status === 'succeeded' ? 'good' : 'warn')}</div></div>`).join('') || '<p class="muted">No collection operations.</p>'; }
function payments() {
  const s = state.ledger, r = s.receipts.find(r => r.id === selectedPayer), chosen = r?.payerId || s.payers[0]?.id;
  return `${tracking() && !s.operations.length ? '<p class="notice">Tracking only: no collection operations. Current payment arrangements are unchanged.</p>' : `<section class="card"><div class="section-head"><h2>${tracking() ? 'Prior collection records · read only' : 'Collection results'}</h2>${tracking() ? '' : button('Stop new collection', 'stop', '', 'danger')}</div>${operationCards(s.operations)}</section>`}<section class="section"><h2>Received receipts and review items</h2><div class="stack section">${s.receipts.filter(r => r.direction !== 'fee').map(r => `<article class="card"><div class="row"><div><h3>${escape(r.payerName || name('payers', r.payerId))} · ${money(r.amountCents)}</h3><p class="muted">${escape(r.provider)} · ${escape(when(r.receivedAt))} · ${escape(r.direction)}</p><p class="${r.reviewReason ? 'error' : 'muted'}">${escape(r.reviewReason || r.classification || 'Allocated to recorded sessions')}</p></div>${r.authenticated && r.status === 'received' && r.direction === 'incoming' ? button('Allocate or classify', 'receipt', r.id) : button('Review source or classify', 'receipt', r.id)}</div></article>`).join('') || empty('No receipts in this ledger. A feed marked disconnected is not evidence that somebody has not paid.')}</div></section>${r ? `<form id="allocate-form" class="card stack section"><h2>Review ${escape(r.provider)} receipt</h2>${r.sourceId ? `<p><a target="_blank" rel="noreferrer" href="https://mail.google.com/mail/u/0/#all/${encodeURIComponent(r.sourceId)}">Inspect the original email</a></p>` : ''}<p class="muted">Authenticated received USD payments can be allocated below. Unknown formats cannot record money; inspect their source, then classify non-business notices without inventing a receipt.</p>${select('Payer', 'payerId', s.payers.map(p => [p.id,p.name]), chosen)}<p class="muted">Use zero for fees this payment does not cover. Session fees and payer-plan periods support partial payment matching. Matching a plan does not split income across tables.</p>${s.obligations.filter(o => balance(s,o.id)>0).map(o => input(`${name('payers',o.payerId)} - ${obligationLabel(o)} - ${money(balance(s,o.id))} left`,o.id,'0.00','number','min="0" step="0.01"')).join('')}<button class="primary" type="submit">Apply this payment to the selected amounts</button><div class="actions">${button('Personal, not business', 'classify-personal', r.id)}${button('Provider transfer', 'classify-transfer', r.id)}</div></form>` : ''}`;
}
function recovery() {
  return `<div class="stack">${tracking() ? '<section class="card"><h2>Tracking-only release</h2><p>This server cannot create payment setup, invoices, charges or retries. Record-only fees remain owed until matched to receipts and stay ineligible for automatic collection, including after a future release.</p></section>' : `<section class="card"><h2>Collection control</h2><p class="muted">Stopping collection holds unstarted work. It preserves every approved fee, receipt, payment attempt and audit entry.</p><div class="actions">${button('Stop new collection', 'stop', '', 'danger')}${button('Enable eligible collection', 'enable')}</div><p class="notice">${state.collectionActivated ? (simulated ? 'Only the fictional provider is enabled in this rehearsal.' : 'The server is activated; feed, consent and balance checks still apply.') : 'This deployment is not activated for payment collection.'}</p></section>`}<section class="card"><h2>Export and recover</h2><p class="muted">Download the ledger and permanent payment-action records. Keep this financial export private. Restoring starts with collection off and requires fresh provider reconciliation.</p><div class="actions">${button('Download private recovery export', 'export')}</div><p class="notice">${simulated ? 'This fictional rehearsal does not create off-site backups.' : 'Encrypted backups are scheduled nightly with 30-day retention. Keep the recovery key separate. <a href="https://github.com/benjaminmanry-dot/20fates-website/actions/workflows/owner-backup.yml" target="_blank" rel="noreferrer">Check recent backup runs</a> before relying on a copy.'}</p></section>${simulated ? '<section class="card"><h2>Opening history</h2><p>Import is disabled in this fictional, login-bypassed rehearsal. Actual records belong only in the approved owner-authenticated service.</p></section>' : `<form id="history-import" class="card stack"><h2>Import history or unresolved drafts</h2><p class="muted">Use the documented 20fates-history/1 file. Unresolved drafts preserve known facts without creating fees, payer links or allocations. Existing identities are retained; imports never initiate collection.</p><label>Private history file<input type="file" name="file" accept="application/json,.json" required></label><label class="inline-check"><input name="confirmed" type="checkbox" required>I checked this file's known facts and unresolved holds, and any included receipt sources and amounts.</label><button type="submit">Import records with collection off</button></form>`}${tracking() ? `<form id="tracking-form" class="card stack"><h2>Review the tracking opening</h2><p class="muted">Confirm the private roster, rates, caps and available opening allocations together. This review cannot verify a missing feed, authorize collection or reopen a closed legacy fee.</p>${input('Earliest fully reviewed tracking date', 'from', state.ledger.settings.trackingFrom || localDate(state.overview.now).slice(0, 7) + '-01', 'date', 'required')}<label class="inline-check"><input name="confirmed" type="checkbox" required>I reviewed the roster, fees and available tracking history.</label><button type="submit">Record the tracking review</button></form>` : `<form id="opening-form" class="card stack"><h2>One opening-balance confirmation</h2><p class="muted">Confirm the complete private roster, individual fees and caps, payer relationships, receipt allocations, opening balances and closed legacy exceptions together. Unknown history must remain marked unknown.</p>${input('First possible automatic-collection date', 'cutoff', localDate(state.overview.now), 'date', 'required')}<label class="inline-check"><input name="confirmed" type="checkbox" required>I reviewed the roster, fees and opening balances.</label><button type="submit">Record the opening review</button></form>`}<section class="card"><h2>Audit history</h2><div class="table-scroll"><table><thead><tr><th>When</th><th>What happened</th><th>Actor</th></tr></thead><tbody>${state.ledger.audit.slice(-50).reverse().map(a => `<tr><td>${escape(when(a.at))}</td><td>${escape(a.type.replaceAll('_',' '))}</td><td>${escape(a.actor)}</td></tr>`).join('')}</tbody></table></div></section></div>`;
}
function closeInput() {
  const form = $('#closeout'), f = new FormData(form), s = state.ledger.sessions.find(s => s.id === selectedSession);
  return { sessionId: s.id, minutes: Number(f.get('minutes')), rows: [...form.querySelectorAll('[data-player]')].map(el => { const id=el.dataset.player, disposition=f.get(`disposition:${id}`); return {playerId:id,attendance:f.get(`attendance:${id}`),disposition,amountCents:dollarsToCents(f.get(`amount:${id}`)),...(disposition==='partial'?{collectCents:dollarsToCents(f.get(`partial:${id}`))}:{}),note:f.get(`note:${id}`),notBefore:f.get(`notBefore:${id}`)||null}; }) };
}
async function run(fn) { if(busy)return;busy=true;const buttons=[...document.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await fn();}catch(e){announce(e.message,true);}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);} }
document.addEventListener('click', e => { const el=e.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;run(async()=>{
  switch(action){
    case 'nav':tab=id;selectedPayer=selectedPlayer=selectedSession=null;review=statementReview=null;render();break;
    case 'refresh':await load('refresh');announce('Feed status and payment outcomes refreshed.');break;
    case 'open-session':tab='sessions';selectedSession=id;review=null;render();break;
    case 'all-sessions':selectedSession=null;review=null;render();break;
    case 'edit-close':review=null;render();break;
    case 'save-draft':await command({type:'saveDraft',input:closeInput()});announce('Draft saved on the private server.');break;
    case 'confirm-close':{const frozen=review;await command({type:'closeSession',input:frozen.input,reviewed:frozen.reviewed});review=null;render();announce(tracking() ? 'Session fees recorded. No payment was requested or queued.' : 'Approved closeout recorded. The server owns the remaining work.');break;}
    case 'cancel-session':{const reason=prompt('Why was this session canceled?');if(reason){await command({type:'cancelSession',sessionId:id,reason});announce('Session canceled; no charge created.');}break;}
    case 'schedule':await command({type:'scheduleOccurrences',through:new Date(Date.parse(state.overview.now)+30*86400000).toISOString().slice(0,10)});announce('Next month’s occurrences recorded.');break;
    case 'player':selectedPlayer=id;selectedPayer=null;render();$('#player-form')?.scrollIntoView({block:'start'});break;
    case 'payer':selectedPayer=id;selectedPlayer=null;statementReview=null;setupLink=null;render();$('#payer-form')?.scrollIntoView({block:'start'});break;
    case 'new-player':selectedPlayer='new';selectedPayer=null;render();$('#player-form')?.scrollIntoView({block:'start'});break;
    case 'new-payer':selectedPayer='new';selectedPlayer=null;render();$('#payer-form')?.scrollIntoView({block:'start'});break;
    case 'setup':{const r=await api({action:'setup',payerId:id,requestId:crypto.randomUUID()});setupLink=r.url;await load();break;}
    case 'revoke':await command({type:'revokeAuthorization',payerId:id});announce('Automatic collection authorization revoked.');break;
    case 'edit-statement':statementReview=null;render();break;
    case 'confirm-statement':{const reviewed=statementReview;await command({type:'collectBalance',id:crypto.randomUUID(),payerId:id,items:reviewed.items,reviewed});statementReview=null;render();break;}
    case 'confirm-plan-period':{const reviewed=planPeriodReview;await command({type:'recordPayerPlanPeriod',planId:reviewed.planId,periodStart:reviewed.periodStart,reviewed});planPeriodReview=null;render();announce('One payer-plan period was recorded once. No table allocation or payment request was created.');break;}
    case 'edit-roster-draft':selectedRosterDraft=id;render();break;
    case 'cancel-roster-draft':selectedRosterDraft=null;render();break;
    case 'resolve-roster-draft':{const resolutionNote=prompt('What confirmed record resolves this draft?');if(resolutionNote){await command({type:'resolveRosterDraft',id,resolutionNote});selectedRosterDraft=null;announce('Draft resolved with its confirmation record; its original facts remain in the audit trail.');}break;}
    case 'receipt':selectedPayer=id;render();break;
    case 'classify-personal':case 'classify-transfer':await command({type:'classifyReceipt',receiptId:id,classification:action==='classify-personal'?'personal':'transfer'});selectedPayer=null;render();break;
    case 'stop':await command({type:'collectionSwitch',enabled:false});announce('New collection stopped. Records preserved.');break;
    case 'enable':await command({type:'collectionSwitch',enabled:true});announce('Eligible collection enabled. Every new batch still needs your confirmation.');break;
    case 'export':{const data=await api({action:'export'}),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`20fates-private-recovery-${localDate(state.overview.now)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);break;}
    case 'signout':clearTimeout(poll);if(auth)await auth.auth.signOut();state=null;login();break;
  }
});});
document.addEventListener('submit', e => { if(!e.target.matches('form'))return;e.preventDefault();const form=e.target,f=new FormData(form),str=k=>String(f.get(k)||'');run(async()=>{
  switch(form.id){
    case 'closeout':{clearTimeout(draftTimer);await draftSave;const input=closeInput();state=await api({action:'command',command:{type:'saveDraft',input}});review={input,reviewed:await api({action:'preview',input})};render();break;}
    case 'player-form':{const id=selectedPlayer==='new'?crypto.randomUUID():selectedPlayer;await command({type:'savePlayer',record:{id,name:str('name'),payerId:str('payerId'),email:str('email'),discord:str('discord'),note:str('note')}});selectedPlayer=id;render();break;}
    case 'payer-form':{const id=selectedPayer==='new'?crypto.randomUUID():selectedPayer;await command({type:'savePayer',record:{id,name:str('name'),email:str('email'),paymentProvider:str('paymentProvider'),stripeCustomerId:str('stripeCustomerId')||null,note:str('note'),aliases:['venmo','cashapp'].filter(x=>str(x)).map(provider=>({provider,name:str(provider)}))}});selectedPayer=id;render();break;}
    case 'authorization-form':await command({type:'recordAuthorization',payerId:selectedPayer,effectiveFrom:str('effectiveFrom'),evidence:str('evidence')});break;
    case 'table-form':await command({type:'saveTable',record:{id:selectedTable||crypto.randomUUID(),name:str('name'),capacity:Number(str('capacity')),weekday:Number(str('weekday')),startTime:str('startTime'),timezone:str('timezone'),normalMinutes:Number(str('normalMinutes')),active:str('active')==='true'}});break;
    case 'membership-form':{const noFee=f.get('noFee') === 'on';await command({type:'saveMembership',record:{id:crypto.randomUUID(),playerId:str('playerId'),tableId:str('tableId'),from:str('from'),rateCents:noFee?0:dollarsToCents(str('rate')),capCents:noFee?0:dollarsToCents(str('cap')),fixedCents:noFee?0:(str('fixed')?dollarsToCents(str('fixed')):null),cadence:str('cadence')}});break;}
    case 'payer-plan-form':await command({type:'savePayerPlan',record:{id:crypto.randomUUID(),payerId:str('payerId'),coveredMembershipIds:f.getAll('coveredMembershipIds').map(String),amountCents:dollarsToCents(str('amount')),cadence:str('cadence'),anchor:str('anchor'),from:str('from'),until:str('until')||null,paidThrough:str('paidThrough')||null,note:str('note')}});break;
    case 'plan-period-form':planPeriodReview=await api({action:'plan-period',input:{planId:str('planId'),periodStart:str('periodStart')}});render();break;
    case 'roster-draft-form':await command({type:'saveRosterDraft',record:{id:selectedRosterDraft||crypto.randomUUID(),label:str('label'),knownFacts:draftLines(str('knownFacts')),aliasHolds:draftLines(str('aliasHolds')),termHolds:draftLines(str('termHolds'))}});selectedRosterDraft=null;break;
    case 'end-membership':await command({type:'endMembership',id:str('id'),until:str('until')});break;
    case 'reschedule':{const s=state.ledger.sessions.find(s=>s.id===selectedSession),startsAt=localToInstant(str('start'),s.timezone);await command({type:'saveSession',record:{id:s.id,tableId:s.tableId,startsAt,endsAt:new Date(Date.parse(startsAt)+Number(str('duration'))*60000).toISOString()}});break;}
    case 'statement-form':{const items=[...f.entries()].map(([obligationId,v])=>({obligationId,amountCents:dollarsToCents(String(v))})).filter(i=>i.amountCents>0);statementReview=await api({action:'statement',payerId:selectedPayer,items});render();break;}
    case 'allocate-form':await command({type:'allocateReceipt',receiptId:selectedPayer,payerId:str('payerId'),allocations:[...f.entries()].filter(([k])=>k!=='payerId').map(([obligationId,v])=>({obligationId,amountCents:dollarsToCents(String(v))})).filter(i=>i.amountCents>0)});selectedPayer=null;render();break;
    case 'tracking-form':await command({type:'confirmTracking',from:str('from'),confirmation:'ROSTER, FEES AND TRACKING HISTORY REVIEWED'});announce('Tracking review recorded. Missing feed evidence stays visible; no collection authorized.');break;
    case 'opening-form':await command({type:'confirmOpening',cutoff:str('cutoff'),confirmation:'ROSTER, FEES AND OPENING BALANCES REVIEWED'});announce('Opening review recorded. Collection remains off.');break;
    case 'history-import':{const file=f.get('file');if(file.size>1500000)throw new Error('History file exceeds the bounded import size');await command({type:'importHistory',data:JSON.parse(await file.text()),confirmation:'RECORD VERIFIED HISTORICAL RECEIPTS'});announce('Historical records imported. No collection was initiated.');break;}
    case 'login-form':{const result=await auth.auth.signInWithPassword({email:str('email'),password:str('password')});if(result.error)throw new Error('Sign-in failed. Check the owner credentials.');await afterLogin();break;}
    case 'mfa-form':{const result=await auth.auth.mfa.challengeAndVerify({factorId:authFactor,code:str('code')});if(result.error)throw new Error('The authenticator code was not accepted.');await load('refresh');break;}
  }
});});
function draftChanged(e){if(e.target.name==='tableEdit'&&e.type==='change'){selectedTable=e.target.value;render();return;}if(e.target.id==='month'&&e.type==='change')run(()=>load());if(e.target.closest('#closeout')&&e.target.name==='minutes'){
  try{const duration=Number(e.target.value),p=previewCloseout(state.ledger,{sessionId:selectedSession,minutes:duration},state.overview.now);for(const r of p.rows){const field=document.getElementsByName(`amount:${r.playerId}`)[0];if(field&&!field.dataset.edited)field.value=(r.amountCents/100).toFixed(2);}$('#duration-label').textContent=`${Math.floor(duration/60)} hours ${duration%60} minutes`;}catch(e){announce(e.message,true);}
}else if(e.target.name?.startsWith('amount:'))e.target.dataset.edited='true';
  if(e.target.closest('#closeout')){clearTimeout(draftTimer);draftTimer=setTimeout(()=>{let input;try{input=closeInput();}catch{return;}draftSave=draftSave.then(async()=>{const saved=await api({action:'command',command:{type:'saveDraft',input}});state=saved;announce('Valid draft saved.');}).catch(e=>announce(e.message,true));},600);}
}
document.addEventListener('input',draftChanged);document.addEventListener('change',draftChanged);
function login(message='') {
  $('#app').innerHTML=`<main id="main" class="card auth"><p class="eyebrow">20Fates · Owner</p><h1>The business behind the table.</h1><p class="muted section">Private records. Owner sign-in and an authenticator are required.</p>${message?`<p class="notice">${escape(message)}</p>`:''}${configured?`<form id="login-form">${input('Owner email','email','','email','required autocomplete="username"')}${input('Password','password','','password','required autocomplete="current-password"')}<button type="submit" class="primary">Sign in</button></form>`:'<p class="notice">The private backend has not been connected. This page contains no private roster or payment records. Complete the approved setup package before activation.</p>'}<p class="section"><a href="/owner/privacy/">About receipt tracking &amp; privacy</a></p></main>`;
}
async function afterLogin(){const {data,error}=await auth.auth.mfa.listFactors();if(error)throw new Error('Authenticator state could not be read');let factor=data.totp.find(f=>f.status==='verified'),qr;
  if(!factor){const enrolled=await auth.auth.mfa.enroll({factorType:'totp',friendlyName:'20Fates owner authenticator'});if(enrolled.error)throw new Error('Authenticator setup needs owner attention');factor=enrolled.data;qr=factor.totp.qr_code;}
  authFactor=factor.id;$('#app').innerHTML=`<main id="main" class="card auth"><p class="eyebrow">Owner verification</p><h1>Your authenticator</h1><p class="muted section">${qr?'Add this account to your authenticator, then enter its code.':'Enter the current six-digit code.'}</p>${qr?`<img alt="Authenticator enrollment QR code" src="${escape(qr)}">`:''}<form id="mfa-form">${input('Six-digit code','code','','text','required inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code" maxlength="6"')}<button type="submit" class="primary">Open the private panel</button></form></main>`;
}
if(simulated)load().catch(e=>login(e.message));else login();
